"""Order totals for the shop. Amounts are whole cents (int)."""

from decimal import Decimal, ROUND_HALF_UP


def _round_to_cents(amount):
    """Round a Decimal (or Decimal-compatible) amount of cents to a whole cent.

    An exact half rounds up: 242.5 -> 243.
    """
    return int(Decimal(amount).quantize(Decimal("1"), rounding=ROUND_HALF_UP))


def _to_decimal_percent(percent):
    """Normalize a percentage that may be int, float or Decimal into an exact Decimal.

    A float means its usual decimal notation: 8.25 means exactly 8.25 percent.
    """
    if isinstance(percent, Decimal):
        return percent
    if isinstance(percent, float):
        return Decimal(str(percent))
    return Decimal(percent)


def line_total(unit_price_cents, quantity, discount_percent=0):
    """Price of one order line in cents after the percentage discount.

    The discounted amount is computed exactly in decimal before rounding to
    whole cents, where an exact half rounds up.
    """
    percent = _to_decimal_percent(discount_percent)
    factor = Decimal(1) - percent / Decimal(100)
    amount = Decimal(unit_price_cents) * Decimal(quantity) * factor
    return _round_to_cents(amount)


def tax(amount_cents, rate_percent):
    """Tax on an amount, in cents.

    Computed exactly in decimal, then rounded to whole cents with halves up.
    """
    rate = _to_decimal_percent(rate_percent)
    amount = Decimal(amount_cents) * rate / Decimal(100)
    return _round_to_cents(amount)


def order_total(lines, tax_rate_percent=0, shipping_cents=0):
    """Total of an order.

    `lines` is a list of (unit_price_cents, quantity, discount_percent).

    The total is the sum of the line totals, the tax on that sum, and shipping.
    """
    subtotal = sum(line_total(*line) for line in lines)
    return subtotal + tax(subtotal, tax_rate_percent) + shipping_cents


def split_evenly(total_cents, parts):
    """Split a total into `parts` shares that add up to exactly `total_cents`.

    Shares differ by at most one cent, with larger shares coming first:
    split_evenly(100, 3) -> [34, 33, 33].

    `parts` below 1 raises ValueError.
    """
    if parts < 1:
        raise ValueError("parts must be at least 1")
    base, extra = divmod(total_cents, parts)
    # `extra` shares get one cent more; larger shares come first.
    return [base + 1] * extra + [base] * (parts - extra)
